script:
// ============ VONATSZIMULÁTOR – villamos mozdony vezetőfülkéje (TRAXX-osztály: 84 t, 5,6 MW, 300 kN, 140 km/h) / TRAIN SIMULATOR – electric locomotive cab (TRAXX-class: 84 t, 5.6 MW, 300 kN, 140 km/h) ============
// Billentyűk: W = gázkar +25 %   S = gázkar −25 % (0 alatt fékezés)   X = nulla   Q = vészfék / Keys: W = throttle +25 %   S = throttle −25 % (below 0 = braking)   X = zero   Q = emergency brake
//       E = rögzítőfék    H = kürt   L = fényszórók / E = parking brake    H = horn   L = headlights
stage(1000, 600, "#0b0d10");
title({hu: "Vonatszimulátor", en: "Train simulator"}, {color: "#25272b"});
plotWindow(120);                                         // a grafikonok az utolsó 2 percet mutatják / graphs show the last 2 minutes

// ---------- vezérlők / controls ----------
param("load", {hu: "Vontatott tömeg (kocsisor)", en: "Trailing load (wagons)"}, 0, 2000, 800, 50, "t");
resetOn("load");                                         // új terhelésnél újraindul a menet / a new load restarts the run
choice("rail", {hu: "Sín állapota", en: "Rail condition"},
  [["dry", {hu: "Száraz (μ = 0,33)", en: "Dry (μ = 0.33)"}],
   ["wet", {hu: "Nedves (μ = 0,22)", en: "Wet (μ = 0.22)"}],
   ["ice", {hu: "Jeges / avar (μ = 0,12)", en: "Icy / leaves (μ = 0.12)"}]], "dry");
choice("tod", {hu: "Napszak", en: "Time of day"},
  [["day", {hu: "Nappal", en: "Day"}], ["dusk", {hu: "Alkonyat", en: "Dusk"}], ["night", {hu: "Éjszaka", en: "Night"}]], "day");
param("dens", {hu: "Világ sűrűsége", en: "World density"}, 0.5, 2, 1.2, 0.1, "×");
toggle("park", {hu: "Rögzítőfék [E]", en: "Parking brake [E]"}, true, {key: "e"});
toggle("lights", {hu: "Fényszórók [L]", en: "Headlights [L]"}, true, {key: "l"});
button({hu: "Újrakezdés [Enter]", en: "Restart [Enter]"}, reset, {key: "Enter"});

// billentyűzet (egy koppintás = egy lenyomás; érintőképernyőn ezek gombok is lesznek) / keyboard (a tap = one press; on touch screens these also become buttons)
onKey("w", () => stepThr(25), {label: {hu: "Gáz +", en: "Throttle +"}, help: {hu: "gázkar +25 % (fék → 0 → húzás)", en: "throttle +25 % (brake → 0 → traction)"}});
onKey("s", () => stepThr(-25), {label: {hu: "Gáz −", en: "Throttle −"}, help: {hu: "gázkar −25 % (0 alatt: fékezés)", en: "throttle −25 % (below 0: braking)"}});
onKey("x", () => { if (!emg) thr = 0; }, {label: {hu: "Nulla", en: "Zero"}, help: {hu: "gázkar nullára", en: "throttle to zero"}});
onKey("q", () => { emg = true; thr = -100; setMsg({hu: "VÉSZFÉK!", en: "EMERGENCY BRAKE!"}); }, {label: {hu: "Vészfék", en: "Emergency"}, help: {hu: "vészfék (megállásig tart)", en: "emergency brake (holds until standstill)"}});
onKey("h", () => { hornT = 1.2; }, {label: {hu: "Kürt", en: "Horn"}, help: {hu: "kürt", en: "horn"}});

// ---------- állandók / constants ----------
const G0 = 9.81;                 // nehézségi gyorsulás (m/s²) / gravitational acceleration (m/s²)
const M_LOCO = 84000;            // a mozdony tömege (kg), 4 tengely / locomotive mass (kg), 4 axles
const P_MAX = 5.6e6;             // teljesítmény a kerekeken (W) / power at the wheels (W)
const F_START = 300e3;           // legnagyobb vonóerő kis sebességnél (N) / maximum tractive effort at low speed (N)
const V_MAX = 140 / 3.6;         // legnagyobb sebesség (m/s) / top speed (m/s)
const F_EB_MAX = 150e3;          // legnagyobb visszatápláló (villamos) fékerő (N) / maximum regenerative (electric) brake force (N)
const P_REG = 4.5e6;             // a visszatápláló fék teljesítményhatára (W) / regenerative brake power limit (W)
const ETA = 0.88;                // a hajtás hatásfoka / drive efficiency
const U_LINE = 25000;            // felsővezetéki feszültség (V) / overhead line voltage (V)
const AUX = 120e3;               // segédüzemek (W) / auxiliaries (W)
const BRK_SERVICE = 0.55;        // tehervonat lassulása teljes üzemi fékezésnél (m/s²) / full service brake deceleration of a freight train (m/s²)
const BRK_EMERG = 0.9;           // lassulás vészfékezésnél (m/s²) / emergency brake deceleration (m/s²)
const KROT = 1.07;               // forgó tömegek: hatásos tömeg = 1,07 × valódi tömeg / rotating masses: effective mass = 1.07 × real mass
const LIM = [100, 80, 120, 60, 100, 90, 120, 80];   // sebességkorlátok (km/h), 2500 m-enként új szakasz / speed limits (km/h), a new zone every 2500 m
const ZONE = 2500;               // szakaszhossz (m) / zone length (m)

// pálya: görbület (1/m, + = jobbkanyar) és lejtés (emelkedés/hossz) az s helyzet (m) függvényében / track: curvature (1/m, + = right bend) and gradient (rise/run) as functions of the position s (m)
function curv(s0) { return 0.0014 * sin(s0 / 900) * sin(s0 / 2300 + 1.2); }
function grade(s0) { return 0.010 * sin(s0 / 1500) + 0.006 * sin(s0 / 610); }        // legfeljebb ±1,6 % / up to ±1.6 %
function limitAt(s0) { return LIM[floor(max(s0, 0) / ZONE) % LIM.length]; }

// ---------- állapot / state ----------
let thr = 0;                     // menetkar, −100…+100 % 25 %-os lépésekben (0 alatt fék) / throttle lever, −100…+100 % in 25 % steps (below 0 = brake)
let trac = 0, bk = 0;            // simított vonóerő- és fékműködtetés (0…1): késleltetve épülnek fel / smoothed traction and brake application (0…1): they build up with a delay
let emg = false;                 // a vészfék működik / emergency brake active
let v = 0, s = 0;                // sebesség (m/s) és helyzet (m) / speed (m/s) and position (m)
let hdg = 0, alt = 120, trip = 0, kwh = 0;   // irány (rad), magasság (m), megtett út (m), energia (kWh) / heading (rad), altitude (m), trip distance (m), energy (kWh)
let rock = 0, clk = 0, hornT = 0;            // a járműszekrény ringásának fázisa, óra, a kürt időzítője / body-rocking phase, clock, horn timer
let Ft = 0, Fe = 0, Fp = 0, Fd = 0, Fres = 0, Fgr = 0, Iel = 0, accS = 0, slip = false;   // a kijelzőkön látható értékek / values shown on the displays
let msgL = "", msgT = 0;
function setMsg(label) { msgL = label; msgT = 3.5; }
setMsg({hu: "Oldd ki a rögzítőféket [E], aztán W", en: "Release the parking brake [E], then press W"});

function stepThr(d) {
  if (emg) { setMsg({hu: "Vészfék: várd meg a megállást", en: "Emergency brake: wait for standstill"}); return; }
  thr = clamp(thr + d, -100, 100);
  if (thr > 0 && P.park) setMsg({hu: "Oldd ki a rögzítőféket [E]!", en: "Release the parking brake [E]!"});
}

// ---------- 2) FIZIKA / PHYSICS ----------
update(dt => {
  const mTot = M_LOCO + P.load * 1000;                   // valódi tömeg (kg) / real mass (kg)
  const mI = mTot * KROT;                                // hatásos (tehetetlen) tömeg / effective (inertial) mass
  const mu = P.rail === "dry" ? 0.33 : P.rail === "wet" ? 0.22 : 0.12;   // tapadás a kerék és a sín között / wheel–rail adhesion
  const vA = abs(v), vOld = v;
  clk += dt; hornT = max(0, hornT - dt); msgT = max(0, msgT - dt);
  if (emg && vA < 0.05) emg = false;                     // álló helyzetben a vészfék old / the emergency brake releases at standstill

  // 1) a mozdonyvezető kérése → a valódi rendszerek késleltetve reagálnak / driver's demand → real systems react with a delay
  const trT = emg ? 0 : max(thr, 0) / 100, bkT = emg ? 1 : max(-thr, 0) / 100;
  trac += clamp(trT - trac, -2 * dt, 0.8 * dt);          // a vonóerő kb. 1,25 s alatt épül fel / traction builds up in ~1.25 s
  const bkRate = bkT > bk ? (emg ? 2 : 0.5) : 0.7;       // a fék lassan húz be (légfék), kicsit gyorsabban old / brakes apply slowly (air brake), release a bit faster
  bk += clamp(bkT - bk, -bkRate * dt, bkRate * dt);

  // 2) vonóerő: kis sebességnél állandó erő, kb. 67 km/h felett állandó teljesítmény (F = P/v), a legnagyobb sebesség felé elhal / traction: constant force at low speed, constant power (F = P/v) above ~67 km/h, fades towards the top speed
  const taper = clamp((V_MAX - vA) / 3, 0, 1);
  const Fav = min(F_START, P_MAX / max(vA, 0.5)) * taper;
  const lock = clamp(1 - (bk - 0.03) * 20, 0, 1);        // amíg a fék be van húzva, nincs vonóerő / no traction while the brake is still applied
  const Fcmd = trac * Fav * lock;
  const Flim = mu * M_LOCO * G0;                         // tapadási határ: csak a mozdony saját súlya hajt / adhesion limit: only the locomotive's own weight drives
  slip = Fcmd > Flim;                                    // a tapadásnál nagyobb kérés → a kerekek megcsúsznak / demand beyond adhesion → the wheels slip
  Ft = slip ? 0.9 * Flim : Fcmd;

  // 3) fékezés: a teljes vonatra kért erő; először a mozdony visszatápláló fékje dolgozik, a többi súrlódó fék / braking: demanded force of the whole train; the loco's regenerative part comes first, the rest is friction
  Fd = bk * (emg ? BRK_EMERG : BRK_SERVICE) * mTot;
  Fe = emg ? 0 : min(Fd, F_EB_MAX, Flim, P_REG / max(vA, 1)) * clamp(vA / 1.5, 0, 1);
  Fp = Fd - Fe;
  const Fb = Fd + (P.park ? 150e3 : 0);                  // a rögzítőfék 150 kN tartóerőt ad hozzá / parking brake adds 150 kN of holding force

  // 4) menetellenállás (mindig a mozgás ellen hat) / running resistance (always opposes the motion)
  const Rc = 1 / max(abs(curv(s)), 1e-4);                // ívsugár (m) / curve radius (m)
  const CdA = 5 + 0.0022 * P.load;                       // légellenállási felület (m²): mozdony + kocsik / drag area (m²): loco + wagons
  Fres = mTot * G0 * (0.0018 + 0.00005 * vA)             // gördülés + csapágy: 1,8 N/kN + sebességfüggő rész / rolling + bearing: 1.8 N/kN + a speed-dependent part
       + 0.5 * 1.2 * CdA * vA * vA                       // légellenállás ½·ρ·CdA·v² / air drag ½·ρ·CdA·v²
       + mTot * G0 * 0.65 / max(Rc - 55, 100);           // ívellenállás (Röckl): a súly 650/(R−55) ‰-e / curve resistance (Röckl): 650/(R−55) ‰ of the weight
  Fgr = -mTot * G0 * grade(s);                           // a nehézségi erő lejtő menti része (emelkedőn negatív) / gravity along the slope (uphill = negative)

  // 5) Newton II. törvénye helyes tapadási súrlódással (a fék nem tolhatja hátra a vonatot) / Newton II with proper static friction (the train cannot be pushed backwards by the brake)
  const Fa = Ft + Fgr, Fo = Fres + Fb;
  if (vA < 0.02 && abs(Fa) <= Fo) v = 0;
  else {
    const sg = vA < 0.02 ? sign(Fa) : sign(v);
    const vN = v + (Fa - sg * Fo) / mI * dt;             // a = (F_hajtó − F_ellenálló) / m_hatásos / a = (F_driving − F_opposing) / m_effective
    v = (vOld !== 0 && vN * vOld < 0) ? 0 : vN;
  }
  s += v * dt;
  if (s < 0) { s = 0; if (v < 0) v = 0; }                // ütközőbak a vonal elején / buffer stop at the start of the line
  hdg += v * curv(s) * dt; alt += v * grade(s) * dt; trip += abs(v) * dt;
  accS += ((v - vOld) / max(dt, 1e-6) - accS) * min(1, 4 * dt);

  // 6) villamos teljesítmény a felsővezetékből (negatív = visszatáplált energia) / electric power from the overhead line (negative = energy fed back)
  const Pel = Ft * max(v, 0) / ETA - Fe * vA * 0.85 + AUX;
  Iel = Pel / (U_LINE * 0.98);
  kwh += Pel * dt / 3.6e6;
  rock += (0.4 + 0.5 * vA) * dt;
});

// ---------- a táj adatai / scenery data ----------
const PAL = {                                            // az ég teteje/horizontja, távoli/közeli talaj, hegyek, fényesség / top/horizon of the sky, far/near ground, mountains, brightness
  day:   {top: [74, 126, 205], hor: [190, 214, 236], gf: [124, 152, 104], gn: [70, 102, 54], mt1: [128, 148, 172], mt2: [96, 116, 134], lum: 1.0, cab: 1.0},
  dusk:  {top: [52, 48, 98], hor: [255, 170, 100], gf: [112, 100, 86], gn: [52, 62, 46], mt1: [110, 90, 116], mt2: [74, 64, 88], lum: 0.62, cab: 0.85},
  night: {top: [4, 6, 18], hor: [26, 32, 56], gf: [22, 28, 34], gn: [12, 18, 14], mt1: [18, 22, 38], mt2: [10, 13, 24], lum: 0.22, cab: 0.5}
};
let PL = PAL.day;
const FL = 700, CAMH = 3.55, CAMX = -0.55;               // fókusztávolság (px), a szem magassága a sín fölött (m), a szem eltolása a pályatengelytől (m) / focal length (px), eye height above the rail (m), eye offset from the track axis (m)
const HZ = 250;                                          // a horizont képernyő-y értéke vízszintes pályán (px); lejjebb = több pálya látszik a műszerfal fölött / screen y of the horizon on level track (px); lower = more track visible above the dash
let OX = 0, OY = 0, YH = 250;                            // képrázkódás és horizontvonal / screen shake and horizon line
const NS = 96, RAT = 1.075, D0 = 2, LNR = log(RAT);      // pályaminták: a távolságok mértani sorban nőnek 2 m-től kb. 1,9 km-ig / track samples: distances grow geometrically from 2 m to ~1.9 km
const SD = [];
for (let i = 0; i < NS; i++) SD.push(D0 * pow(RAT, i));
const SLAT = new Array(NS).fill(0), SZR = new Array(NS).fill(0);   // az előttünk lévő pálya oldalirányú eltolása és magassága (a fülkéhez képest) / lateral offset and height of the track ahead (relative to the cab)
const IS = ceil(log(9 / D0) / LNR), IW = ceil(log(8 / D0) / LNR);

function hash(i, j) { const q = sin(i * 12.9898 + j * 78.233) * 43758.5453; return q - floor(q); }
function mixc(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }
function rgbS(c) { return "rgb(" + floor(clamp(c[0], 0, 255)) + "," + floor(clamp(c[1], 0, 255)) + "," + floor(clamp(c[2], 0, 255)) + ")"; }
function shadeC(c, d) {                                  // éjszakai/alkonyati sötétítés, a fényszóró erősítése a közelben, pára a távolsággal / night/dusk darkening, headlight boost nearby, haze with distance
  const boost = P.lights ? (1 - PL.lum) * 0.8 * clamp(1 - d / 160, 0, 1) : 0;
  const L = PL.lum + boost;
  return mixc([c[0] * L, c[1] * L, c[2] * L], PL.hor, 1 - exp(-d / 900));
}
function sx(X, d) { return 500 + OX + FL * X / d; }      // perspektíva: X oldaltávolság (m) d távolságban (m) → képernyő-x / perspective: lateral X (m) at distance d (m) → screen x
function sy(H, d) { return HZ + OY - FL * H / d; }       // H magasság a szemhez képest (m) → képernyő-y / height H relative to the eye (m) → screen y
function tri(w) { return 0.3 * (2 * abs(mod(w / 65, 2) - 1) - 1); }   // a munkavezeték cikcakkja, ±0,3 m / contact-wire zig-zag, ±0.3 m
function buildTrack(g0) {                                // a görbület és a lejtés összegzése a mozdony előtt / integrate curvature and gradient ahead of the loco
  let h = 0, lat = 0, z = 0, dPrev = 0;
  for (let i = 0; i < NS; i++) {
    const d = SD[i], mid = s + (dPrev + d) / 2, st = d - dPrev;
    const hN = h + curv(mid) * st;                       // irányváltozás ezen a darabon / heading change over this piece
    lat += (h + hN) / 2 * st;                            // oldalirányú eltérés / sideways drift
    z += (grade(mid) - g0) * st;                         // magasság a fülke érintővonalához képest / height relative to the cab's tangent line
    h = hN; dPrev = d;
    SLAT[i] = lat; SZR[i] = z;
  }
}
function atD(d) {                                        // a pálya eltolása és magassága tetszőleges távolságban / track offset and height at an arbitrary distance
  const f = log(max(d, D0) / D0) / LNR, i = clamp(floor(f), 0, NS - 2), k = clamp(f - i, 0, 1);
  return [SLAT[i] + (SLAT[i + 1] - SLAT[i]) * k, SZR[i] + (SZR[i + 1] - SZR[i]) * k];
}
function range(col, amp, f1, f2, ph) {                   // távoli hegyek egy rétege; az iránnyal együtt elmozdul / a layer of distant mountains; it shifts as the heading changes
  const pts = [[0, YH + 2]];
  for (let x = 0; x <= 1000; x += 20) {
    const th = hdg + atan((x - 500) / FL);
    pts.push([x, YH - amp * (0.55 + 0.3 * sin(f1 * th + ph) + 0.15 * sin(f2 * th + 2 * ph))]);
  }
  pts.push([1000, YH + 2]);
  polygon(pts, {fill: rgbS(col), stroke: null});
}

// ---------- műszerek / instruments ----------
function dial(cx, cy, r, val, vmax, majors, label, redFrom) {
  circle(cx, cy, r + 4, {fill: "#15161a", stroke: "#5a5d63", lw: 2});
  circle(cx, cy, r, {fill: "#0b0c0f", stroke: null});
  const a0 = deg(135), sp = deg(270);                    // a skála 270°-ot fog át az óramutató járása szerint, a bal alsó részről indulva / the scale sweeps 270° clockwise from the lower left
  for (let i = 0; i <= majors; i++) {
    const a = a0 + sp * i / majors;
    line(cx + (r - 7) * cos(a), cy + (r - 7) * sin(a), cx + (r - 2) * cos(a), cy + (r - 2) * sin(a), {stroke: "#d8d8d8", lw: 1.5});
  }
  if (redFrom < vmax) arc(cx, cy, r - 4, a0 + sp * redFrom / vmax, a0 + sp, {stroke: "#d6453a", lw: 3});
  const an = a0 + sp * clamp(val / vmax, 0, 1);
  line(cx, cy, cx + (r - 8) * cos(an), cy + (r - 8) * sin(an), {stroke: "#ffb347", lw: 2});
  circle(cx, cy, 3, {fill: "#cccccc", stroke: null});
  text(fmt(val, 1), cx, cy + r * 0.6, {size: 9, color: "#9fd0ff", align: "center"});
  text(label, cx, cy + r + 15, {size: 10, color: "#c9cdd2", align: "center"});
}
function lamp(x, y, w, h, label, on, col) {
  rect(x, y, w, h, {fill: on ? col : "#1d1f23", stroke: "#4a4d53", lw: 1.5, radius: 4});
  text(label, x + w / 2, y + h / 2 + 3.5, {size: 9, bold: true, color: on ? "#101010" : "#6a6e75", align: "center"});
}

// a fülke körvonala (képernyő-koordináták) / cab outline (screen coordinates)
const ROOF = [[0, 0], [1000, 0], [1000, 106], [940, 122], [522, 100], [478, 100], [60, 122], [0, 106]];
const ROOF2 = [[0, 70], [1000, 70], [1000, 106], [940, 122], [522, 100], [478, 100], [60, 122], [0, 106]];
const PANE_L = [[60, 122], [478, 100], [474, 396], [66, 404]];
const PANE_R = [[522, 100], [940, 122], [934, 404], [526, 396]];
const PIL_L = [[0, 106], [60, 122], [66, 404], [0, 444]];
const PIL_R = [[1000, 106], [940, 122], [934, 404], [1000, 444]];
const PIL_C = [[478, 100], [522, 100], [526, 396], [474, 396]];
const DASH = [[0, 444], [66, 404], [474, 396], [526, 396], [934, 404], [1000, 444], [1000, 600], [0, 600]];
const COWL = [[0, 444], [66, 404], [474, 396], [526, 396], [934, 404], [1000, 444], [1000, 458], [934, 420], [526, 410], [474, 410], [66, 420], [0, 458]];

// ---------- 3) RAJZOLÁS / DRAWING ----------
draw(t => {
  PL = PAL[P.tod] || PAL.day;
  const kmh = abs(v) * 3.6, lim = limitAt(s), g0 = grade(s);
  const vf = clamp(abs(v) / 20, 0, 1);
  OX = 1.4 * vf * sin(rock * 1.7) + 0.7 * vf * sin(rock * 4.1);                  // nagyobb sebességnél a fülke jobban ring / the cab rocks more at speed
  OY = 1.6 * vf * sin(rock * 2.3 + 1) - clamp(accS * 5, -6, 6);                  // fékezéskor pedig kicsit bólint / and dips a little when braking
  YH = HZ + OY + FL * g0;                                                        // emelkedőn a horizont lejjebb kerül / the horizon drops when climbing
  buildTrack(g0);

  // --- ég, nap/hold, hegyek, talaj / sky, sun/moon, mountains, ground ---
  for (let y = 0; y < YH; y += 14) rect(0, y, 1000, 15, {fill: rgbS(mixc(PL.top, PL.hor, pow(clamp(y / max(YH, 1), 0, 1), 1.5))), stroke: null});
  const sunX = 500 + OX + FL * tan(0.35 - hdg);
  if (sunX > -80 && sunX < 1080) {
    if (P.tod === "day") { circle(sunX, YH - 120, 46, {fill: "#fff3b0", stroke: null, alpha: 0.2}); circle(sunX, YH - 120, 22, {fill: "#fffbe0", stroke: null}); }
    else if (P.tod === "dusk") { circle(sunX, YH - 28, 60, {fill: "#ff9a50", stroke: null, alpha: 0.25}); circle(sunX, YH - 28, 26, {fill: "#ffd9a0", stroke: null}); }
    else { circle(sunX, YH - 130, 26, {fill: "#9fb4ff", stroke: null, alpha: 0.15}); circle(sunX, YH - 130, 14, {fill: "#eef2ff", stroke: null}); }
  }
  range(mixc(PL.mt1, PL.hor, 0.35), 78, 2.3, 6.1, 1.0);
  range(PL.mt2, 44, 3.7, 9.3, 2.1);
  range(shadeC([36, 70, 46], 600), 16, 23, 41, 0.7);     // távoli erdősáv / far treeline
  for (let y = YH; y < 600; y += 20) rect(0, y, 1000, 21, {fill: rgbS(mixc(PL.gf, PL.gn, clamp((y - YH) / 260, 0, 1))), stroke: null});

  // --- földek a pálya mellett: vetés-, fű- és talajcsíkok, 140 m-enként változnak / fields beside the track: strips of crops, grass and soil that change every 140 m ---
  const CROP = [[142, 160, 84], [176, 158, 88], [104, 134, 72], [122, 96, 70], [158, 174, 98], [92, 120, 66]];
  for (let i = NS - 2; i >= IS; i--) {
    const d0 = SD[i], d1 = SD[i + 1], fi = floor((s + d0) / 140);
    const X0 = SLAT[i] - CAMX, X1 = SLAT[i + 1] - CAMX, z0 = SZR[i] - CAMH - 1.0, z1 = SZR[i + 1] - CAMH - 1.0;
    for (let sd = -1; sd <= 1; sd += 2) {
      const col = rgbS(shadeC(CROP[floor(hash(fi, 20 + sd) * CROP.length)], d0));
      polygon([[sx(X0 + sd * 5, d0), sy(z0, d0)], [sx(X0 + sd * 60, d0), sy(z0, d0)], [sx(X1 + sd * 60, d1), sy(z1, d1)], [sx(X1 + sd * 5, d1), sy(z1, d1)]],
              {fill: col, stroke: col, lw: 1});
    }
  }
  // --- töltés, sötét zúzottkő és világos beton kábelcsatornák (minden darab a távolsággal beleolvad a párába) / embankment, dark ballast and light concrete cable ducts (each piece fades into the haze with distance) ---
  for (let i = IS; i < NS - 1; i++) {
    const d0 = SD[i], d1 = SD[i + 1], X0 = SLAT[i] - CAMX, X1 = SLAT[i + 1] - CAMX, z0 = SZR[i] - CAMH, z1 = SZR[i + 1] - CAMH;
    const cb = rgbS(shadeC([112, 118, 84], d0)), cs = rgbS(shadeC([84, 82, 80], d0)), cd = rgbS(shadeC([176, 174, 168], d0));
    polygon([[sx(X0 - 4.8, d0), sy(z0 - 1.0, d0)], [sx(X0 + 4.8, d0), sy(z0 - 1.0, d0)], [sx(X1 + 4.8, d1), sy(z1 - 1.0, d1)], [sx(X1 - 4.8, d1), sy(z1 - 1.0, d1)]], {fill: cb, stroke: cb, lw: 1});
    polygon([[sx(X0 - 2.45, d0), sy(z0 - 0.25, d0)], [sx(X0 + 2.45, d0), sy(z0 - 0.25, d0)], [sx(X1 + 2.45, d1), sy(z1 - 0.25, d1)], [sx(X1 - 2.45, d1), sy(z1 - 0.25, d1)]], {fill: cs, stroke: cs, lw: 1});
    for (let sd = -1; sd <= 1; sd += 2)
      polygon([[sx(X0 + sd * 2.6, d0), sy(z0 - 0.2, d0)], [sx(X0 + sd * 3.1, d0), sy(z0 - 0.2, d0)], [sx(X1 + sd * 3.1, d1), sy(z1 - 0.2, d1)], [sx(X1 + sd * 2.6, d1), sy(z1 - 0.2, d1)]], {fill: cd, stroke: cd, lw: 1});
