  // --- betonaljak: világosak a sötét zúzottkövön; nagy sebességnél kicsit halványulnak (különben villognának) / concrete sleepers: light on dark ballast; they fade a little at speed (they would strobe) ---
  const sleepA = clamp(0.95 - kmh * 0.005, 0.3, 0.9);
  for (let k = ceil((s + 9) / 0.65); ; k++) {
    const d = k * 0.65 - s;
    if (d > 75) break;
    const q = atD(d), X = q[0] - CAMX, H = q[1] - CAMH - 0.12, w = clamp(FL * 0.26 / d, 1, 7);
    line(sx(X - 1.35, d), sy(H, d), sx(X + 1.35, d), sy(H, d), {stroke: rgbS(shadeC([168, 166, 158], d)), lw: w, alpha: sleepA * (1 - d / 95)});
  }
  // --- sínek: sötét árnyékvonal, fényes acél sínfej, vékony csillogás a közelebbi részen / rails: dark shadow line, bright steel head, thin shine on the nearer part ---
  for (let i = IS; i < NS - 1; i++) for (const sd of [-1, 1]) {
    const d0 = SD[i], d1 = SD[i + 1], X0 = SLAT[i] - CAMX + sd * 0.7175, X1 = SLAT[i + 1] - CAMX + sd * 0.7175;
    const x0 = sx(X0, d0), y0 = sy(SZR[i] - CAMH, d0), x1 = sx(X1, d1), y1 = sy(SZR[i + 1] - CAMH, d1);
