  // --- felsővezeték (munkavezeték + tartósodrony) / overhead wires (contact wire + messenger wire) ---
  const cw = [], mw = [];
  for (let i = IW; i < NS; i++) {
    const d = SD[i], w = s + d, X = SLAT[i] - CAMX + tri(w);
