  // --- tárgyak a pálya mentén, távolról közelre: oszlopok, fák, bokrok, kerítések, házak, sebességjelzők / lineside objects, far to near: masts, trees, bushes, fences, houses, speed signs ---
  const items = [];
  for (let k = ceil((s + 8) / 65); k * 65 - s < 900; k++) {          // felsővezeték-oszlopok 65 m-enként / catenary masts every 65 m
