  // fák: 10 m-es szeletenként és oldalanként két jelölt; a sűrűség csúszka szabja meg, hány létezik belőlük / trees: two candidates per 10 m slice and side; the density slider sets how many of them exist
  for (let k = floor((s + 12) / 10); k * 10 - s < 600; k++) for (let sd = -1; sd <= 1; sd += 2) for (let j = 0; j < 2; j++) {
