      if (kind < 0.55) {                                             // tűlevelű: két egymásra rakott háromszög / conifer: two stacked triangles
        polygon([[bx - pw * 0.55, by - ph * 0.18], [bx + pw * 0.55, by - ph * 0.18], [bx, by - ph * 0.62]], {fill: rgbS(shadeC([28, 68, 42], d)), stroke: null});
        polygon([[bx - pw * 0.42, by - ph * 0.45], [bx + pw * 0.42, by - ph * 0.45], [bx, by - ph]], {fill: rgbS(shadeC([36, 82, 50], d)), stroke: null});
