  }
  // kerítésdrótok (oldalanként kettő), a tárgyak előtt rajzolva, hogy az oszlopok eléjük kerüljenek / fence wires (two per side), drawn before the objects so the posts stand in front of them
  for (const sd of [-1, 1]) for (const hgt of [-0.3, 0.4]) {
    const pts = [];
