  // ===== A VEZETŐFÜLKE / THE CAB =====
  const cl = PL.cab;
  const B1 = rgbS([190 * cl, 188 * cl, 178 * cl]), B2 = rgbS([164 * cl, 162 * cl, 153 * cl]);
  const DK = rgbS([46 * cl, 48 * cl, 52 * cl]), DK3 = rgbS([28 * cl, 29 * cl, 32 * cl]);
