  polygon([[560, 104], [640, 106], [590, 394], [548, 394]], {fill: "#ffffff", stroke: null, alpha: 0.03});
  polygon(ROOF, {fill: B1, stroke: null});
  polygon(ROOF2, {fill: B2, stroke: null, alpha: 0.5});
  polygon(PIL_L, {fill: B2, stroke: null});
