  polygon(PIL_C, {fill: B2, stroke: null});
  rect(396, 0, 208, 52, {fill: DK, stroke: "#222428", lw: 2, radius: 4});                                   // felső kapcsolótábla / overhead switch panel
  for (let i = 0; i < 8; i++) {
    rect(408 + i * 24, 12, 14, 9, {fill: i % 3 === 0 ? "#d6453a" : "#7d8188", stroke: null, radius: 2});
    rect(408 + i * 24, 30, 14, 9, {fill: i % 2 === 0 ? "#3fbf6a" : "#555960", stroke: null, radius: 2});
