  polygon(DASH, {fill: DK, stroke: null});
  polygon(COWL, {fill: DK3, stroke: null});
  rect(20, 458, 960, 142, {fill: "#2a2c31", stroke: "#15161a", lw: 2, radius: 8});                          // műszerfal / instrument face

  // menetszabályozó (gáz- és fékkar) / master controller (throttle / brake lever)
  const lc = thr > 0 ? "#e8963a" : thr < 0 ? "#e0483c" : "#9aa0a8";
  rect(40, 464, 180, 130, {fill: "#202226", stroke: "#3b3e44", lw: 1.5, radius: 6});
  text({hu: "MENETKAR", en: "THROTTLE"}, 130, 478, {size: 10, bold: true, color: "#9aa0a8", align: "center"});
  text((thr > 0 ? "+" : "") + thr + " %", 130, 494, {size: 14, bold: true, color: lc, align: "center"});
  rect(122, 502, 16, 84, {fill: "#0c0d0f", stroke: "#555a61", lw: 1.5, radius: 4});
