  // sebességmérő 0…160 km/h, jelölt korláttal: alatta zöld, fölötte piros / speedometer 0…160 km/h with the limit marked: green below, red above
  const scx = 350, scy = 527, sr = 58, sa0 = deg(135), ssp = deg(270), sAng = k => sa0 + ssp * clamp(k / 160, 0, 1);
