  text(fmt(kmh, 0), 520, 505, {size: 38, bold: true, color: over ? (flash ? "#ff4a3a" : "#ffb0a8") : "#ffffff", align: "center"});
  text("km/h", 520, 520, {size: 11, color: "#9aa0a8", align: "center"});
  circle(630, 497, 24, {fill: "#ffffff", stroke: "#d62a2a", lw: 5});
  text(String(lim), 630, 504, {size: 19, bold: true, color: "#111111", align: "center"});
  if (over && flash) text({hu: "SEBESSÉGHATÁR TÚLLÉPVE", en: "SPEED LIMIT EXCEEDED"}, 562, 478, {size: 10, bold: true, color: "#ff4a3a", align: "center"});
  rect(465, 534, 200, 9, {fill: "#1b1f26", stroke: null});
