  const grLine = tr({hu: "Lejtő ", en: "Grade "}) + (g0 >= 0 ? "+" : "") + fmt(g0 * 100, 1) + " %   " + tr({hu: "Áram ", en: "Current "}) + fmt(Iel, 0) + " A";
