  // nyomásmérők és figyelmeztető lámpák / pressure gauges and warning lamps
  const bpBar = emg ? 0 : 5.0 - 1.5 * clamp(bk, 0, 1), bcBar = Fd > 1 ? 3.8 * clamp(bk, 0, 1.2) * (Fp / Fd) : 0, mrBar = 9.0 - 0.6 * clamp(bk, 0, 1);
  dial(745, 498, 28, mrBar, 10, 10, {hu: "FL", en: "MR"}, 10);
